CREATE TYPE "GuidanceCaseStatus" AS ENUM ('OPEN','IN_PROGRESS','CLOSED');
CREATE TYPE "GuidanceCasePriority" AS ENUM ('LOW','MEDIUM','HIGH','URGENT');
CREATE TABLE "guidance_cases" ("id" UUID NOT NULL DEFAULT gen_random_uuid(),"school_id" UUID NOT NULL,"report_id" UUID NOT NULL,"priority" "GuidanceCasePriority" NOT NULL DEFAULT 'MEDIUM',"status" "GuidanceCaseStatus" NOT NULL DEFAULT 'OPEN',"action_plan_encrypted" TEXT,"referral_encrypted" TEXT,"follow_up_at" TIMESTAMPTZ(3),"closed_at" TIMESTAMPTZ(3),"created_at" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMPTZ(3) NOT NULL,CONSTRAINT "guidance_cases_pkey" PRIMARY KEY ("id"),CONSTRAINT "guidance_cases_school_id_report_id_key" UNIQUE ("school_id","report_id"),CONSTRAINT "guidance_cases_school_id_fkey" FOREIGN KEY ("school_id") REFERENCES "schools"("id") ON DELETE CASCADE,CONSTRAINT "guidance_cases_report_id_fkey" FOREIGN KEY ("report_id") REFERENCES "safety_reports"("id") ON DELETE RESTRICT);
CREATE INDEX "guidance_cases_school_id_status_priority_idx" ON "guidance_cases"("school_id","status","priority");
CREATE TABLE "guidance_case_assignments" ("id" UUID NOT NULL DEFAULT gen_random_uuid(),"school_id" UUID NOT NULL,"case_id" UUID NOT NULL,"user_id" UUID NOT NULL,"elevated" BOOLEAN NOT NULL DEFAULT false,"created_at" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMPTZ(3) NOT NULL,CONSTRAINT "guidance_case_assignments_pkey" PRIMARY KEY ("id"),CONSTRAINT "guidance_case_assignments_case_id_user_id_key" UNIQUE ("case_id","user_id"),CONSTRAINT "guidance_case_assignments_case_id_fkey" FOREIGN KEY ("case_id") REFERENCES "guidance_cases"("id") ON DELETE CASCADE,CONSTRAINT "guidance_case_assignments_user_id_fkey" FOREIGN KEY ("user_id") REFERENCES "users"("id") ON DELETE CASCADE);
CREATE INDEX "guidance_case_assignments_school_id_user_id_idx" ON "guidance_case_assignments"("school_id","user_id");
CREATE TABLE "guidance_case_notes" ("id" UUID NOT NULL DEFAULT gen_random_uuid(),"school_id" UUID NOT NULL,"case_id" UUID NOT NULL,"author_user_id" UUID NOT NULL,"content_encrypted" TEXT NOT NULL,"created_at" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMPTZ(3) NOT NULL,CONSTRAINT "guidance_case_notes_pkey" PRIMARY KEY ("id"),CONSTRAINT "guidance_case_notes_case_id_fkey" FOREIGN KEY ("case_id") REFERENCES "guidance_cases"("id") ON DELETE CASCADE,CONSTRAINT "guidance_case_notes_author_user_id_fkey" FOREIGN KEY ("author_user_id") REFERENCES "users"("id") ON DELETE RESTRICT);
CREATE INDEX "guidance_case_notes_school_id_case_id_created_at_idx" ON "guidance_case_notes"("school_id","case_id","created_at");
